const express = require('express');
const OpenApiValidator = require('express-openapi-validator');
const path = require('path');
const { CustodyVault, WalletRegistry } = require('../services/vault');

const app = express();
app.use(express.json());

app.use(
  OpenApiValidator.middleware({
    apiSpec: path.join(__dirname, 'specs', 'custody-openapi.yaml'),
    validateRequests: true
  })
);

app.get('/api/v1/custody/wallets/:walletAddress/keystore', async (req, res) => {
  if (!req.user || !req.user.id) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { walletAddress } = req.params;

  // Confirm that the authenticated user is the verified owner of the custodial wallet
  const ownership = await WalletRegistry.findOne({
    where: {
      address: walletAddress.toLowerCase(),
      ownerUserId: req.user.id
    }
  });

  if (!ownership) {
    return res.status(403).json({ error: 'Access denied: caller does not own this custodial wallet' });
  }

  const keystoreData = await CustodyVault.getEncryptedKeystore(walletAddress);
  if (!keystoreData) {
    return res.status(404).json({ error: 'Wallet keystore not found in custody vault' });
  }

  res.json({
    walletAddress,
    cryptoKeystore: keystoreData.encryptedJson,
    derivationPath: keystoreData.derivationPath,
    algorithm: keystoreData.algorithm
  });
});

app.listen(5007);
